			["CColonys1"] = "Colony Foundation",
			["CColonys2"] = "Create your own colony and unlock numerous new features for you and your friends. Establishing a colony costs you $2500 and 1000g of brain mass. Interested?",
			["CColonys3"] = "Colony Name:",
			["CColonys4"] = "Create Colony",
			["CColonys5"] = "Your colony starts with 5 vehicle slots and 5 member slots. By killing zombies, colony experience points are earned, which unlock additional slots and colony functions.",
			["CColonys6"] = "Your colony name must be between 1 and 24 characters long.",
			["CColonys7"] = "Members",
			["CColonys8"] = "Player",
			["CColonys9"] = "Rank",
			["CColonys10"] = "Warnings",
			["CColonys11"] = "Join Date",
			["CColonys12"] = "Last Login",
			["CColonys13"] = "Status",
			["CColonys14"] = "Add Warning",
			["CColonys15"] = "Remove Warning",
			["CColonys16"] = "Remove Player",
			["CColonys17"] = "Promote",
			["CColonys18"] = "Demote",
			["CColonys19"] = "Player:",
			["CColonys20"] = "Invite Player",
			["CColonys21"] = "Laboratories",
			["CColonys22"] = "A laboratory that was abandoned after the outbreak of the apocalypse. However, the equipment still works. It can be used to research the virus.\n\nFight against other colonies for control of the laboratories and gain bonuses for your colony.",
			["CColonys23"] = "How does a fight for a laboratory work?",
			["CColonys24"] = "If your colony owns this laboratory, it receives the following bonuses on colony payday:\n- %s experience points\n- %s brain mass\n- $%s",
			["CColonys25"] = "[ INFO ]",
			["CColonys26"] = "Bonus 1",
			["CColonys27"] = "Bonus 2",
			["CColonys28"] = "Bonus 3",
			["CColonys29"] = "Bonus 4",
			["CColonys30"] = "Bonus 5",
			["CColonys31"] = "Bonus 6",
			["CColonys32"] = "Locked for %s more hours.",
			["CColonys33"] = "Laboratory",
			["CColonys34"] = "Bonus 1\nThis bonus grants the colony a one-time bonus of 500 experience points * the colony's current level. Additionally, the colony receives 750 extra experience points for each colony member who is online at the time the bonus is activated.\nTo activate this bonus, the colony must own at least 2 laboratories. This bonus can be activated every 6 hours.\n\nClick the button again to activate the bonus.",
			["CColonys35"] = "Bonus 2\nThis bonus grants the colony a one-time bonus of $125 * the colony's current level. Additionally, the colony receives $125 extra for each colony member who is online at the time the bonus is activated.\nTo activate this bonus, the colony must own at least 4 laboratories. This bonus can be activated every 6 hours.\n\nClick the button again to activate the bonus.",
			["CColonys36"] = "Bonus 3\nThis bonus grants the colony a one-time bonus of 10 brain mass * the colony's current level. Additionally, the colony receives 10 extra brain mass for each colony member who is online at the time the bonus is activated.\nTo activate this bonus, the colony must own at least 6 laboratories. This bonus can be activated every 12 hours.\n\nClick the button again to activate the bonus.",
			["CColonys37"] = "Bonus 4\nThis bonus grants the colony a one-time bonus of 250 random loot items. Additionally, the colony receives 10 extra loot items for each colony member who is online at the time the bonus is activated.\nTo activate this bonus, the colony must own at least 8 laboratories. This bonus can be activated every 12 hours.\n\nClick the button again to activate the bonus.",
			["CColonys38"] = "Bonus 5\nThis bonus grants the colony a one-time bonus of one additional player slot and one additional vehicle slot.\nTo activate this bonus, the colony must own at least 10 laboratories. This bonus can be activated every 336 hours.\n\nClick the button again to activate the bonus.",
			["CColonys39"] = "Bonus 6\nThis bonus grants the colony a one-time level up.\nTo activate this bonus, the colony must own all laboratories. This bonus can be activated every 168 hours.\n\nClick the button again to activate the bonus.",
			["CColonys40"] = "Capture laboratories to unlock a total of 6 different bonuses. Click on a bonus to see what it does. Then click it again to activate it.",
			["CColonys41"] = "Attackers:",
			["CColonys42"] = "1. Go to the laboratory you want to attack.",
			["CColonys43"] = "2. Look for the attack point and start the attack there.",
			["CColonys44"] = "3. After a preparation phase of 30 seconds, the attack officially begins.",
			["CColonys45"] = "4. An attack lasts 15 minutes, during which attackers must collect points. 700 points are required for victory.",
			["CColonys46"] = "5. Points are collected when at least one player of the colony is at the attack point.",
			["CColonys47"] = "Defenders:",
			["CColonys48"] = "1. If one of your laboratories is attacked, you will be notified.",
			["CColonys49"] = "2. Prevent the attackers from collecting points by killing enemies at the laboratory's attack point.",
			["CColonys50"] = "3. If the attackers do not reach 700 points after 15 minutes, you have successfully defended your laboratory.",
			["CColonys51"] = "Zombies",
			["CColonys52"] = "Go to Area 51 to buy zombies and experiment on them.",
			["CColonys53"] = "Total experience points collected: %s",
			["CColonys54"] = "Total zombies killed: %s",
			["CColonys55"] = "%s/%s experience points until level %s",
			
