			["CWarehouse1"] = "Choose how many crates you want to transport. You pay $150 for one crate. At the delivery point you receive $750 and $250 per crate and a rocket launcher with one shot. But be careful: if your vehicle takes damage, crates can fall off and be lost.",
			["CWarehouse2"] = "Start transport for $%s (%s/8 crates)",
			["CWarehouse3"] = "Rule No. 1: The crates stay closed! If you know what’s inside them, I have to kill you.",
			["CWarehouse4"] = "I only assign contracts to members of a colony.",
			["CWarehouse5"] = "Goods Delivery",
			["CWarehouse6"] = "As a member of a colony, you have the opportunity to carry out a delivery mission here. You can select up to 8 crates, each costing $150. You will then receive a transporter filled with goods and a drop-off location marked with a [GRAY TRUCK] on the map. Upon arrival at the destination, you will receive $750 and $250 per crate. But be careful: drive cautiously so that no crate falls off! If all crates fall off, the delivery fails.",

