			["CHelpmenu1"] = "Hilfemenü",
			["CHelpmenu2"] = "Erkunde die Welt und schalte neue Einträge für dein Hilfemenü frei, um mehr über San Andreas Apocalypse zu erfahren.",
			["CHelpmenu3"] = "Eintrag",
			["CHelpmenu4"] = "Startseite",
			["CHelpmenu5"] = "Willkommen im Hilfemenü!\n\nDieses Hilfemenü ist deine umfassende Informationsquelle, um die verschiedenen Funktionen und Mechaniken unseres Spiels besser zu verstehen. Ob du ein neuer Spieler bist, der die Grundlagen erlernen möchte, oder ein erfahrener Spieler, der sein Wissen auffrischen will – hier findest du alle wichtigen Informationen.\n\nIn den folgenden Abschnitten werden die verschiedenen Aspekte des Spiels detailliert erläutert, darunter das Adminsystem, die Benutzeroberfläche, Collectibles, das Levelsystem, Looting, NPCs, Schutzzonen, Shops und vieles mehr. Du erhältst wertvolle Einblicke in die Spielmechaniken, die dir helfen, deine Spielerfahrung zu maximieren und das volle Potenzial des Spiels auszuschöpfen.\n\nNutze die Suchfunktion, um gezielt Informationen zu finden, oder blättere durch die Kategorien, um alles zu entdecken, was unser Spiel zu bieten hat. Bei weiteren Fragen kannst du dich jederzeit an die Community oder die Administratoren wenden.\n\nViel Spaß und Erfolg im Spiel!",
			
