			["CColonys3"] = "Kolonie Name:",
			["CColonys4"] = "Kolonie gründen",
			["CColonys5"] = "Deine Kolonie startet mit 5 Fahrzeug- und 5 Mitgliederplätzen. Durch das Töten von Zombies werden Kolonie-Erfahrungspunkte gesammelt, die weitere Plätze und Kolonie-Funktionen freischalten.",
			["CColonys6"] = "Der Name deiner Kolonie muss aus zwischen 1 - 24 Zeichen bestehen.",
			["CColonys7"] = "Mitglieder",
			["CColonys8"] = "Spieler",
			["CColonys9"] = "Rang",
			["CColonys10"] = "Warns",
			["CColonys11"] = "Beitrittsdatum",
			["CColonys12"] = "Letzter Login",
			["CColonys13"] = "Status",
			["CColonys14"] = "Warn hinzufügen",
			["CColonys15"] = "Warn entfernen",
			["CColonys16"] = "Spieler entfernen",
			["CColonys17"] = "Befördern",
			["CColonys18"] = "Degradieren",
			["CColonys19"] = "Spieler:",
			["CColonys20"] = "Spieler einladen",
			["CColonys21"] = "Labore",
			["CColonys22"] = "in Labor, welches nach dem Ausbruch der Apokalypse verlassen wurde. Doch die Geräte funktionieren noch. Mit ihnen kann der Virus erforscht werden.\n\nKämpft gegen andere Kolonien um die Labore und erhaltet Bonis für eure Kolonie.",
			["CColonys23"] = "Wie funktioniert ein Kampf um ein Labor?",
			["CColonys24"] = "Dieses Labor bringt deiner Kolonie bei Besitz am Kolonie-Payday folgende Bonis:\n- %s Erfahrungspunkte\n- %s Hirnmasse\n- $%s",
			["CColonys25"] = "[ INFO ]",
			["CColonys26"] = "Bonus 1",
			["CColonys27"] = "Bonus 2",
			["CColonys28"] = "Bonus 3",
			["CColonys29"] = "Bonus 4",
			["CColonys30"] = "Bonus 5",
			["CColonys31"] = "Bonus 6",
			["CColonys32"] = "Noch %s Stunden gesperrt.",
			["CColonys33"] = "Labor",
			["CColonys34"] = "Bonus 1\nDieser Bonus verschafft der Kolonie einen einmaligen Bonus von 500 Erfahrungspunkte * dem derzeitigen Level der Kolonie. Außerdem erhält die Kolonie 750 zustätzliche Erfahrungspunkte pro Mitglied der Kolonie, das zum Zeitpunkt, an dem der Bonus aktiviert wird, online ist.\nZum Aktivieren dieses Bonus muss die Kolonie im Besitz von mindestens 2 Laboren sein. Dieser Bonus kann alle 6 Stunden aktiviert werden.\n\nKlicke erneut auf den Button, um den Bonus zu aktivieren.",
			["CColonys35"] = "Bonus 2\nDieser Bonus verschafft der Kolonie einen einmaligen Bonus von $125 * dem derzeitigen Level der Kolonie. Außerdem erhält die Kolonie $125 zusätzlich pro Mitglied der Kolonie, das zum Zeitpunkt, an dem der Bonus aktiviert wird, online ist.\nZum Aktivieren dieses Bonus muss die Kolonie im Besitz von mindestens 4 Laboren sein. Dieser Bonus kann alle 6 Stunden aktiviert werden.\n\nKlicke erneut auf den Button, um den Bonus zu aktivieren.",
			["CColonys36"] = "Bonus 3\nDieser Bonus verschafft der Kolonie einen einmaligen Bonus von 10 Hirnmasse * dem derzeitigen Level der Kolonie. Außerdem erhält die Kolonie 10 zusätzliche Hirnmasse pro Mitglied der Kolonie, das zum Zeitpunkt, an dem der Bonus aktiviert wird, online ist.\nZum Aktivieren dieses Bonus muss die Kolonie im Besitz von mindestens 6 Laboren sein. Dieser Bonus kann alle 12 Stunden aktiviert werden.\n\nKlicke erneut auf den Button, um den Bonus zu aktivieren.",
			["CColonys37"] = "Bonus 4\nDieser Bonus verschafft der Kolonie einen einmaligen Bonus von 250 zufälligen Loot-Items. Außerdem erhält die Kolonie 10 zusätzliche Loot-Items pro Mitglied der Kolonie, das zum Zeitpunkt, an dem der Bonus aktiviert wird, online ist.\nZum Aktivieren dieses Bonus muss die Kolonie im Besitz von mindestens 8 Laboren sein. Dieser Bonus kann alle 12 Stunden aktiviert werden.\n\nKlicke erneut auf den Button, um den Bonus zu aktivieren.",
			["CColonys38"] = "Bonus 5\nDieser Bonus verschafft der Kolonie einen einmaligen Bonus von einem weiteren Spieler- und einem weiteren Fahrzeugslot.\nZum Aktivieren dieses Bonus muss die Kolonie im Besitz von mindestens 10 Laboren sein. Dieser Bonus kann alle 168 Stunden aktiviert werden.\n\nKlicke erneut auf den Button, um den Bonus zu aktivieren.",
			["CColonys39"] = "Bonus 6\nDieser Bonus verschafft der Kolonie einen einmaligen Levelaufstieg.\nZum Aktivieren dieses Bonus muss die Kolonie im Besitz von allen Laboren sein. Dieser Bonus kann alle 168 Stunden aktiviert werden.\n\nKlicke erneut auf den Button, um den Bonus zu aktivieren.",
			["CColonys40"] = "Erobert Labore, um insgesamt 6 verschiedene Bonis freizuschalten. Klicke auf einen Bonus, um zu erfahren, was er bringt. Klicke anschließend ein weiteres Mal auf ihn, um ihn zu aktivieren.",
			["CColonys41"] = "Angreifer:",
			["CColonys42"] = "1. Begibt euch zu dem Labor, das ihr angreifen wollt.",
			["CColonys43"] = "2. Sucht nach dem Angriffspunkt und startet an diesem den Angriff.",
			["CColonys44"] = "3. Nach einer Vorbereitungsphase von 30 Sekunden, hat der Angriff offiziell begonnen.",
			["CColonys45"] = "4. Ein Angriff dauert 15 Minuten, in denen man als Angreifer Punkte sammeln muss. Für einen Sieg werden 700 Punkte benötigt.",
			["CColonys46"] = "5. Punkte werden gesammelt, wenn sich mindestens ein Spieler der Kolonie an dem Angriffspunkt befindet.",
			["CColonys47"] = "Verteidiger:",
			["CColonys48"] = "1. Wenn eines eurer Labore angegriffen wird, werdet ihr benachrichtigt.",
			["CColonys49"] = "2. Haltet die Angreifer davon ab, Punkte zu sammeln, indem ihr die Gegner am Angriffspunkt des Labor tötet.",
			["CColonys50"] = "3. Wenn die Angreifer nach 15 Minuten keine 700 Punkte erreicht haben, habt ihr euer Labor verteidigt.",
			["CColonys51"] = "Zombies",
			["CColonys52"] = "Begib dich in die Area 51, um Zombies zu kaufen und an ihnen zu experimentieren.",
			["CColonys53"] = "Insgesamt gesammelte Erfahrungspunkte: %s",
			["CColonys54"] = "Insgesamt getötete Zombies: %s",
			["CColonys55"] = "%s/%s Erfahrungspunkte bis Level %s",
			
