			["CWrenchGame2"] = "Punkte: %s/%s - Fehlversuche: %s/%s",
			["CWrenchGame3"] = "Mist, ich habe zu viele Schraubenschlüssel verfehlt.",
			
			["SWrenchGame1"] = "Perfekt! Ein Motor und 4 Reifen.",
			
			["SMechanicSkill1"] = "Jetzt kann ich mich mit dem Fahrzeug wieder blicken lassen.",
			["SMechanicSkill2"] = "Ich brauche %s Repairkits, um dieses Fahrzeug reparieren zu können.",
			["SMechanicSkill3"] = "Dieses Fahrzeug muss nicht repariert werden.",
			
			["SWaterDispenser1"] = "Das hat gut getan.",
			
			["CStreetCleaner1"] = "Müll eingesammelt\n%s/500",
			
			["SStreetCleaner1"] = "Du hast noch nicht genug Müll eingesammelt.",
			["SStreetCleaner2"] = "Wunderbar! Und schon ist die Welt wieder ein stück sauberer.",
			
			["SChainsaw1"] = "Bring mir 10 rostige Kettensägen.",
			["SChainsaw2"] = "Großartig, du hast sie gefunden. Hier, eine funktionierende Kettensäge.",
			
			["CWarehouse1"] = "Wähle aus, wie viele Kisten du transportieren möchtest. Für eine Kiste zahlst du $150. Am Abgabeort erhältst du $750 und $250 pro Kiste und einen Raketenwerfer mit einem Schuss. Doch Achtung: Nimmt dein Fahrzeug Schaden, können Kisten herunterfallen und verloren gehen.",
			["CWarehouse2"] = "Transport für $%s starten (%s/8 Kisten)",
			["CWarehouse3"] = "Regel Nr. 1: Die Kisten bleiben zu! Wenn du weißt, was in ihnen ist, muss ich dich töten.",
			["CWarehouse4"] = "Ich habe nur Aufträge an Mitglieder einer Kolonie zu vergeben.",
			["CWarehouse5"] = "Warenauslieferung",
			["CWarehouse6"] = "Als Mitglied einer Kolonie hast du hier die Möglichkeit, einen Auslieferungsauftrag auszuführen. Du kannst bis zu 8 Kisten auswählen, die dich je $150 Kosten. Anschließend erhältst du den mit der Ware gefüllten Transporter und den Abgabeort, der mit einem [GRAUEN LKW] auf der Karte markiert wird. Am Abgabepunkt angekommen, erhältst du $750 und $250 pro Kiste. Doch Achtung: Fahr vorsichtig, damit keine Kiste herunterfällt! Wenn alle Kisten heruntergefallen sind, ist die Lieferung fehlgeschlagen.",
			
