			["SWeaponTransport8"] = "Was für eine Fahrt!",
			["SWeaponTransport9"] = "Ich habe zurzeit keine Aufträge.. schau doch später noch einmal vorbei.",
			["SWeaponTransport10"] = "Waffentransport",
			["SWeaponTransport11"] = "Hier kannst du mit zwei weiteren Spielern einen Waffentransport organisieren. Jeder von euch bekommt ein Boot, mit dem die Waffen dann an ihr Ziel gebracht werden müssen. Das Ziel hängt davon ab, ob man Teil einer Kolonie ist, das ein Warenhaus besitzt, oder nicht. Bei erfolgreicher Auslieferung erhältst du unter anderem ein Waffenpaket.",
