			["CHelpmenu3"] = "Запись",
			["CHelpmenu4"] = "Главная",
			["CHelpmenu5"] = "Добро пожаловать в меню помощи!\n\nЭто меню помощи служит вашим всеобъемлющим источником информации, чтобы лучше понять различные функции и механики нашей игры. Независимо от того, являетесь ли вы новым игроком, желающим изучить основы, или опытным игроком, который хочет освежить знания, здесь вы найдёте всю важную информацию.\n\nВ следующих разделах подробно объясняются различные аспекты игры, включая систему администрирования, пользовательский интерфейс, коллекционные предметы, систему уровней, обыск, NPC, безопасные зоны, магазины и многое другое. Вы получите ценные сведения о механиках игры, которые помогут вам максимально эффективно использовать игровой процесс и раскрыть весь потенциал игры.\n\nИспользуйте функцию поиска, чтобы найти конкретную информацию, или просматривайте категории, чтобы узнать всё, что может предложить наша игра. Если у вас возникнут дополнительные вопросы, вы всегда можете обратиться к сообществу или администраторам.\n\nУдачи и приятной игры!",

