			["CColonys1"] = "Основание колонии",
			["CColonys2"] = "Создайте свою собственную колонию и откройте множество новых возможностей для себя и своих друзей. Основание колонии стоит $2500 и 1000 г мозговой массы. Интересно?",
			["CColonys3"] = "Название колонии:",
			["CColonys4"] = "Создать колонию",
			["CColonys5"] = "Ваша колония начинается с 5 слотов для транспорта и 5 слотов для участников. Убивая зомби, вы получаете опыт колонии, который открывает дополнительные слоты и функции колонии.",
			["CColonys6"] = "Название вашей колонии должно содержать от 1 до 24 символов.",
			["CColonys7"] = "Участники",
			["CColonys8"] = "Игрок",
			["CColonys9"] = "Ранг",
			["CColonys10"] = "Предупреждения",
			["CColonys11"] = "Дата вступления",
			["CColonys12"] = "Последний вход",
			["CColonys13"] = "Статус",
			["CColonys14"] = "Добавить предупреждение",
			["CColonys15"] = "Убрать предупреждение",
			["CColonys16"] = "Исключить игрока",
			["CColonys17"] = "Повысить",
			["CColonys18"] = "Понизить",
			["CColonys19"] = "Игрок:",
			["CColonys20"] = "Пригласить игрока",
			["CColonys21"] = "Лаборатории",
			["CColonys22"] = "Лаборатория, заброшенная после начала апокалипсиса. Однако оборудование всё ещё работает. Её можно использовать для исследования вируса.\n\nСражайтесь с другими колониями за контроль над лабораториями и получайте бонусы для своей колонии.",
			["CColonys23"] = "Как проходит борьба за лабораторию?",
			["CColonys24"] = "Если ваша колония владеет этой лабораторией, она получает следующие бонусы при выплате колониального дохода:\n- %s очков опыта\n- %s мозговой массы\n- $%s",
			["CColonys25"] = "[ ИНФО ]",
			["CColonys26"] = "Бонус 1",
			["CColonys27"] = "Бонус 2",
			["CColonys28"] = "Бонус 3",
			["CColonys29"] = "Бонус 4",
			["CColonys30"] = "Бонус 5",
			["CColonys31"] = "Бонус 6",
			["CColonys32"] = "Заблокировано ещё на %s часов.",
			["CColonys33"] = "Лаборатория",
			["CColonys34"] = "Бонус 1\nЭтот бонус даёт колонии разовый бонус в размере 500 очков опыта * текущий уровень колонии. Кроме того, колония получает дополнительно 750 очков опыта за каждого участника колонии, который находится онлайн в момент активации бонуса.\nДля активации этого бонуса колония должна владеть как минимум 2 лабораториями. Этот бонус можно активировать каждые 6 часов.\n\nНажмите кнопку ещё раз, чтобы активировать бонус.",
			["CColonys35"] = "Бонус 2\nЭтот бонус даёт колонии разовый бонус в размере $125 * текущий уровень колонии. Кроме того, колония получает дополнительно $125 за каждого участника колонии, который находится онлайн в момент активации бонуса.\nДля активации этого бонуса колония должна владеть как минимум 4 лабораториями. Этот бонус можно активировать каждые 6 часов.\n\nНажмите кнопку ещё раз, чтобы активировать бонус.",
			["CColonys36"] = "Бонус 3\nЭтот бонус даёт колонии разовый бонус в размере 10 единиц мозговой массы * текущий уровень колонии. Кроме того, колония получает дополнительно 10 единиц мозговой массы за каждого участника колонии, который находится онлайн в момент активации бонуса.\nДля активации этого бонуса колония должна владеть как минимум 6 лабораториями. Этот бонус можно активировать каждые 12 часов.\n\nНажмите кнопку ещё раз, чтобы активировать бонус.",
			["CColonys37"] = "Бонус 4\nЭтот бонус даёт колонии разовый бонус в размере 250 случайных предметов добычи. Кроме того, колония получает дополнительно 10 предметов добычи за каждого участника колонии, который находится онлайн в момент активации бонуса.\nДля активации этого бонуса колония должна владеть как минимум 8 лабораториями. Этот бонус можно активировать каждые 12 часов.\n\nНажмите кнопку ещё раз, чтобы активировать бонус.",
			["CColonys38"] = "Бонус 5\nЭтот бонус даёт колонии разовый бонус в виде одного дополнительного слота игрока и одного дополнительного слота транспорта.\nДля активации этого бонуса колония должна владеть как минимум 10 лабораториями. Этот бонус можно активировать каждые 336 часов.\n\nНажмите кнопку ещё раз, чтобы активировать бонус.",
			["CColonys39"] = "Бонус 6\nЭтот бонус даёт колонии разовое повышение уровня.\nДля активации этого бонуса колония должна владеть всеми лабораториями. Этот бонус можно активировать каждые 168 часов.\n\nНажмите кнопку ещё раз, чтобы активировать бонус.",
			["CColonys40"] = "Захватывайте лаборатории, чтобы разблокировать всего 6 различных бонусов. Нажмите на бонус, чтобы узнать, что он даёт. Затем нажмите на него ещё раз, чтобы активировать его.",
			["CColonys41"] = "Атакующие:",
			["CColonys42"] = "1. Отправляйтесь к лаборатории, которую вы хотите атаковать.",
			["CColonys43"] = "2. Найдите точку атаки и начните атаку в ней.",
			["CColonys44"] = "3. После подготовительной фазы в 30 секунд атака официально начинается.",
			["CColonys45"] = "4. Атака длится 15 минут, в течение которых атакующие должны набирать очки. Для победы требуется 700 очков.",
			["CColonys46"] = "5. Очки начисляются, если хотя бы один игрок колонии находится на точке атаки.",
			["CColonys47"] = "Защитники:",
			["CColonys48"] = "1. Если одна из ваших лабораторий подвергнется атаке, вы будете уведомлены.",
			["CColonys49"] = "2. Не дайте атакующим набирать очки, убивая врагов на точке атаки лаборатории.",
			["CColonys50"] = "3. Если атакующие не наберут 700 очков за 15 минут, вы успешно защитили свою лабораторию.",
			["CColonys51"] = "Зомби",
