			["CHelpmenu5"] = "Bem-vindo ao Menu de Ajuda!\n\nEste Menu de Ajuda serve como sua fonte completa de informações para entender melhor as várias funções e mecânicas do nosso jogo. Seja você um novo jogador querendo aprender o básico ou um jogador experiente querendo relembrar conhecimentos, encontrará aqui todas as informações importantes.\n\nNas seções seguintes, os diferentes aspectos do jogo são explicados em detalhes, incluindo o sistema de administração, interface do usuário, colecionáveis, sistema de níveis, saque, NPCs, zonas seguras, lojas e muito mais. Você obterá informações valiosas sobre as mecânicas do jogo que o ajudarão a maximizar sua experiência e desbloquear todo o potencial do jogo.\n\nUse a função de pesquisa para encontrar informações específicas ou navegue pelas categorias para descobrir tudo o que nosso jogo tem a oferecer. Se tiver mais dúvidas, sinta-se à vontade para entrar em contato com a comunidade ou com os administradores.\n\nDivirta-se e boa sorte no jogo!",

