			["CColonys1"] = "Fundação da Colônia",
			["CColonys2"] = "Crie sua própria colônia e desbloqueie inúmeros novos recursos para você e seus amigos. Fundar uma colônia custa $2500 e 1000g de massa cerebral. Interessado?",
			["CColonys3"] = "Nome da Colônia:",
			["CColonys4"] = "Criar Colônia",
			["CColonys5"] = "Sua colônia começa com 5 slots de veículos e 5 slots de membros. Ao matar zumbis, pontos de experiência da colônia são obtidos, desbloqueando slots adicionais e funções da colônia.",
			["CColonys6"] = "O nome da sua colônia deve ter entre 1 e 24 caracteres.",
