			["CColonys18"] = "Rebaixar",
			["CColonys19"] = "Jogador:",
			["CColonys20"] = "Convidar Jogador",
			["CColonys21"] = "Laboratórios",
			["CColonys22"] = "Um laboratório abandonado após o início do apocalipse. No entanto, os equipamentos ainda funcionam. Eles podem ser usados para pesquisar o vírus.\n\nLute contra outras colônias pelo controle dos laboratórios e ganhe bônus para sua colônia.",
			["CColonys23"] = "Como funciona uma luta por um laboratório?",
			["CColonys24"] = "Se sua colônia possuir este laboratório, ela receberá os seguintes bônus no payday da colônia:\n- %s pontos de experiência\n- %s massa cerebral\n- $%s",
			["CColonys25"] = "[ INFO ]",
			["CColonys26"] = "Bônus 1",
			["CColonys27"] = "Bônus 2",
			["CColonys28"] = "Bônus 3",
			["CColonys29"] = "Bônus 4",
			["CColonys30"] = "Bônus 5",
			["CColonys31"] = "Bônus 6",
			["CColonys32"] = "Bloqueado por mais %s horas.",
			["CColonys33"] = "Laboratório",
			["CColonys34"] = "Bônus 1\nEste bônus concede à colônia um bônus único de 500 pontos de experiência * o nível atual da colônia. Além disso, a colônia recebe 750 pontos de experiência extras para cada membro online no momento da ativação.\nPara ativar este bônus, a colônia deve possuir pelo menos 2 laboratórios. Este bônus pode ser ativado a cada 6 horas.\n\nClique novamente no botão para ativar o bônus.",
			["CColonys35"] = "Bônus 2\nEste bônus concede à colônia um bônus único de $125 * o nível atual da colônia. Além disso, a colônia recebe $125 extras para cada membro online no momento da ativação.\nPara ativar este bônus, a colônia deve possuir pelo menos 4 laboratórios. Este bônus pode ser ativado a cada 6 horas.\n\nClique novamente no botão para ativar o bônus.",
			["CColonys36"] = "Bônus 3\nEste bônus concede à colônia um bônus único de 10 massa cerebral * o nível atual da colônia. Além disso, a colônia recebe 10 massa cerebral extras para cada membro online no momento da ativação.\nPara ativar este bônus, a colônia deve possuir pelo menos 6 laboratórios. Este bônus pode ser ativado a cada 12 horas.\n\nClique novamente no botão para ativar o bônus.",
			["CColonys37"] = "Bônus 4\nEste bônus concede à colônia um bônus único de 250 itens aleatórios de loot. Além disso, a colônia recebe 10 itens extras para cada membro online no momento da ativação.\nPara ativar este bônus, a colônia deve possuir pelo menos 8 laboratórios. Este bônus pode ser ativado a cada 12 horas.\n\nClique novamente no botão para ativar o bônus.",
			["CColonys38"] = "Bônus 5\nEste bônus concede à colônia um bônus único de um slot adicional de jogador e um slot adicional de veículo.\nPara ativar este bônus, a colônia deve possuir pelo menos 10 laboratórios. Este bônus pode ser ativado a cada 336 horas.\n\nClique novamente no botão para ativar o bônus.",
			["CColonys39"] = "Bônus 6\nEste bônus concede à colônia um aumento de nível único.\nPara ativar este bônus, a colônia deve possuir todos os laboratórios. Este bônus pode ser ativado a cada 168 horas.\n\nClique novamente no botão para ativar o bônus.",
			["CColonys40"] = "Capture laboratórios para desbloquear um total de 6 bônus diferentes. Clique em um bônus para ver o que ele faz. Depois clique novamente para ativá-lo.",
			["CColonys41"] = "Atacantes:",
			["CColonys42"] = "1. Vá até o laboratório que deseja atacar.",
			["CColonys43"] = "2. Procure o ponto de ataque e inicie o ataque lá.",
			["CColonys44"] = "3. Após uma fase de preparação de 30 segundos, o ataque começa oficialmente.",
			["CColonys45"] = "4. Um ataque dura 15 minutos, durante os quais os atacantes devem coletar pontos. 700 pontos são necessários para a vitória.",
			["CColonys46"] = "5. Os pontos são coletados quando pelo menos um jogador da colônia está no ponto de ataque.",
			["CColonys47"] = "Defensores:",
			["CColonys48"] = "1. Se um dos seus laboratórios for atacado, você será notificado.",
			["CColonys49"] = "2. Impessa os atacantes de coletarem pontos matando os inimigos no ponto de ataque do laboratório.",
			["CColonys50"] = "3. Se os atacantes não alcançarem 700 pontos após 15 minutos, você terá defendido seu laboratório com sucesso.",
